function videoPanel(roomUrl,stopAttendance,resumeAttendance){
 const panel=el('section',null,'video-panel'),status=el('p','카메라·마이크를 점검한 뒤 화상방을 여세요.','small');status.setAttribute('role','status');
 const preview=el('video');preview.autoplay=true;preview.muted=true;preview.playsInline=true;preview.setAttribute('aria-label','내 기기 미리보기 · 상대와 통화 중이 아님');preview.hidden=true;
 const controls=el('div',null,'actions'),frameBox=el('div');let stream=null,frame=null,busy=false,disposed=false,generation=0;
 function tracks(kind){return stream?.getTracks().filter(t=>t.kind===kind&&t.readyState==='live')||[];}
 function releasePreview(){stream?.getTracks().forEach(t=>t.stop());stream=null;preview.srcObject=null;preview.hidden=true;sync();}
 function sync(){mic.disabled=!tracks('audio').length;camera.disabled=!tracks('video').length;switchCamera.disabled=!tracks('video').length;mic.textContent=tracks('audio').some(t=>t.enabled)?'마이크 끄기':'마이크 켜기';camera.textContent=tracks('video').some(t=>t.enabled)?'카메라 끄기':'카메라 켜기';}
 function errorText(e){return ({NotAllowedError:'카메라·마이크 권한이 허용되지 않았습니다. 수업 계정 로그인으로 해결되는 문제가 아닙니다.',NotFoundError:'사용 가능한 카메라 또는 마이크를 찾지 못했습니다.',NotReadableError:'다른 앱이 장치를 사용 중일 수 있습니다. 장치를 확인해 주세요.'})[e.name]||'장치를 시작하지 못했습니다. 브라우저의 카메라·마이크 설정을 확인해 주세요.';}
 const start=button('카메라·마이크 미리보기',async()=>{
  if(busy||disposed)return;
  if(!navigator.mediaDevices?.getUserMedia){status.textContent='이 브라우저에서는 장치 접근을 지원하지 않습니다. HTTPS 주소에서 확인해 주세요.';return;}
  if(frame){status.textContent='화상방을 먼저 종료한 뒤 기기 미리보기를 시작하세요.';return;}
  busy=true;const attempt=++generation;
  try{const next=await navigator.mediaDevices.getUserMedia({audio:true,video:{facingMode:'user'}});
   if(disposed||attempt!==generation){next.getTracks().forEach(t=>t.stop());return;}
   releasePreview();stream=next;preview.srcObject=stream;preview.hidden=false;sync();status.textContent='내 기기 미리보기입니다. 상대 영상·음성 송수신 성공을 뜻하지 않습니다.';
  }catch(e){if(!disposed&&attempt===generation)status.textContent=errorText(e);}finally{busy=false;}
 });
 const mic=button('마이크 끄기',()=>{const active=tracks('audio').some(t=>t.enabled);tracks('audio').forEach(t=>t.enabled=!active);sync();});
 const camera=button('카메라 끄기',()=>{const active=tracks('video').some(t=>t.enabled);tracks('video').forEach(t=>t.enabled=!active);sync();});
 const switchCamera=button('카메라 전환',async()=>{
  if(busy||disposed||!tracks('video').length)return;busy=true;const attempt=++generation;
  try{const devices=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='videoinput');
   if(devices.length<2){status.textContent='전환 가능한 두 번째 카메라가 없습니다.';return;}
   const current=tracks('video')[0],index=devices.findIndex(d=>d.deviceId===current.getSettings().deviceId);
   const next=await navigator.mediaDevices.getUserMedia({audio:false,video:{deviceId:{exact:devices[(index+1)%devices.length].deviceId}}});
   if(disposed||attempt!==generation||!stream){next.getTracks().forEach(t=>t.stop());return;}
   const replacement=next.getVideoTracks()[0];replacement.enabled=current.enabled;stream.removeTrack(current);stream.addTrack(replacement);current.stop();preview.srcObject=stream;sync();status.textContent='미리보기 카메라를 전환했습니다.';
  }catch(e){if(!disposed&&attempt===generation)status.textContent=errorText(e);}finally{busy=false;}
 });
 const embed=button('이 화면에서 화상방 열기',async()=>{
  if(disposed||frame)return;const attempt=++generation;releasePreview();await resumeAttendance();
  if(disposed||attempt!==generation){stopAttendance();return;}
  frame=el('iframe');frame.title='Jitsi 수업 화상방';frame.allow='camera; microphone; fullscreen; display-capture';frame.allowFullscreen=true;frame.referrerPolicy='no-referrer';frame.src=roomUrl;frameBox.append(frame);
  status.textContent='외부 Jitsi 화면을 열었습니다. 연결 성공 여부는 상대 영상·음성으로 확인해야 합니다. 진행자 인증이 막히면 위의 새 창 링크를 사용하세요. 한글쉽지 로그인을 반복하지 마세요.';
 });
 const end=button('기기·화상방 종료',()=>{generation++;releasePreview();frameBox.replaceChildren();frame=null;stopAttendance();status.textContent='기기와 이 화면의 화상방을 종료했습니다. 새 창으로 연 Jitsi 방은 그 창에서 나가야 합니다. 수업 완료 처리는 별도입니다.';});
 add(controls,start,mic,camera,switchCamera,embed,end);add(panel,el('h3','수업 화상 화면'),notice('미리보기는 내 기기 점검입니다. 실제 통화에서는 Jitsi 화면의 마이크·카메라·나가기 버튼을 사용하세요.'),preview,controls,status,frameBox);sync();
 const dialog=$('#detail-dialog');
 function dispose(){if(disposed)return;disposed=true;generation++;releasePreview();frameBox.replaceChildren();frame=null;stopAttendance();observer.disconnect();dialog.removeEventListener('close',dispose);pageDocument.defaultView.removeEventListener('pagehide',dispose);}
 const observer=new MutationObserver(()=>{if(!panel.isConnected)dispose();});observer.observe($('#detail'),{childList:true});dialog.addEventListener('close',dispose);pageDocument.defaultView.addEventListener('pagehide',dispose);
 return panel;
}
async function joinRoom(b){
 const box=$('#detail');let joined=false;
 box.replaceChildren(el('h2','테스트 화상방 안내'),
  notice('공개 Jitsi 서비스의 테스트 방입니다. 인증된 비공개 수업이 아니며 링크를 아는 제3자가 입장할 수 있습니다. 민감한 정보 공유와 녹화는 하지 마세요. 외부 서비스의 이용 조건과 개인정보 처리가 적용됩니다.'),
  el('p',state.user.id===b.teacher_id?'강사는 Jitsi 방을 먼저 시작하세요. meet.jit.si는 방을 처음 여는 사람에게 별도의 Jitsi 계정 인증을 요구할 수 있습니다.':'강사가 방을 시작한 뒤 같은 링크로 참여하세요. Jitsi의 진행자 대기 화면에서는 한글쉽지 로그인을 반복할 필요가 없습니다.'),
  notice('인증 구분: 테스트 서버 접속 비밀번호 / 한글쉽지 수업 계정 / 외부 Jitsi 진행자 인증은 서로 다릅니다. Jitsi에 테스트 서버 비밀번호를 입력하지 마세요.'),
  el('p','출석 시간은 이 화면에서 30초마다 서버에 확인합니다. 이 기록만으로 실제 수업 이행이 입증되지 않으며, 양측 확인과 관리자 증빙 검토가 추가로 필요합니다.'));
 const a=button('안내 확인 · 출석 시작',async()=>{
  if(joined)return;
  const x=await api(`/api/bookings/${b.id}/join`,'POST',{}),url=new URL(x.roomUrl);
  if(url.protocol!=='https:'||url.hostname!=='meet.jit.si')throw Error('허용되지 않은 회의 주소입니다.');
  const link=el('a','Jitsi 테스트 방을 새 창에서 열기','primary');link.href=url.href;link.target='_blank';link.rel='noopener noreferrer';
  box.append(link,button('공유 교재 열기',()=>unitDialog(x.unitId,b.id)));joined=true;a.hidden=true;
  clearInterval(state.heartbeat);let heartbeat=null;
  const stop=()=>{clearInterval(heartbeat);heartbeat=null;};
  const begin=()=>{heartbeat=setInterval(()=>api(`/api/bookings/${b.id}/attendance`,'POST',{}).catch(e=>{stop();message(e.message,true);}),30000);state.heartbeat=heartbeat;};
  begin();box.append(videoPanel(url.href,stop,async()=>{if(heartbeat)return;await api(`/api/bookings/${b.id}/join`,'POST',{});begin();}));
 });box.append(a);$('#detail-dialog').showModal();
}
