async function business(root){add(root,section('사업이 지속될 수 있는 가격을 찾습니다','수수료와 추천 보상률은 확정되지 않았습니다. 아래는 가정값의 거래별 공헌이익이며 최종 순이익이 아닙니다.'));const form=el('form',null,'form-grid card'),[pw,p]=field('1회 수업 모의 가격 · 원','price','number',20000),[tw,t]=field('세금 충당 가정 · % · 법정 세율 아님','tax','number',0),[rw,r]=field('환불 비용 충당 가정 · %','refund','number',3);p.min=1000;p.max=1000000;t.min=r.min=0;t.max=r.max=100;t.step=r.step='.1';add(form,pw,tw,rw);const b=el('button','시나리오 계산','primary');b.type='submit';form.append(b);root.append(form);const result=el('div',null,'card');root.append(result);async function calculate(){const x=await api(`/api/scenarios?price=${Number(p.value)}&taxBps=${Math.round(Number(t.value)*100)}&refundBps=${Math.round(Number(r.value)*100)}`);result.replaceChildren(notice(x.note));result.append(table(['수수료','직접 추천','수업 매출','강사 몫','추천 보상','PG 가정','환불 충당','세금 충당','거래 공헌이익'],x.scenarios.map(s=>[`${s.commissionBps/100}%`,`${s.referralBps/100}%`,money(s.gross),money(s.teacher),money(s.referral),money(s.processor),money(s.refund),money(s.tax),money(s.platform)])));result.append(el('p','고정비·인건비·실제 납부세액·국가별 환율 및 수수료·미회수 비용은 포함되지 않습니다. 선택형 강사 서비스, 프리미엄 콘텐츠, 기업 교육은 별도 사업 검증이 필요합니다.','small'));}form.onsubmit=e=>{e.preventDefault();run(calculate,b);};await calculate();}
async function admin(root){if(state.user?.role!=='admin'){root.append(notice('테스트 관리자 계정으로 로그인해야 합니다. 관리자 권한은 회원가입으로 부여할 수 없습니다.'));return;}add(root,section('운영 관리 · 모든 기록은 테스트용','실제 신원·자격 확인이나 금전 지급을 의미하지 않습니다. 판단 근거는 감사 기록으로 남습니다.'));const x=await api('/api/admin');const stats=el('div',null,'grid');[['전체 회원',x.users.length],['수업 예약',x.bookings.length],['미처리 분쟁',x.disputes.filter(d=>d.status==='open').length]].forEach(([k,v])=>stats.append(add(el('div',null,'card'),el('p',k,'muted'),el('div',v,'kpi'))));root.append(stats);const total=kind=>x.ledger.filter(e=>e.kind===kind||e.kind===kind+'_reversal').reduce((n,e)=>n+e.amount,0);const finance=el('div',null,'card');add(finance,el('h3','모의 거래 수익과 지급 발생액'),notice('아래 금액은 테스트 원장 합계입니다. 실제 결제 매출·현금 잔액·출금 가능액이 아닙니다.'),table(['항목','모의 금액'],[['환불 반영 테스트 수납',money(total('test_charge'))],['플랫폼 거래 공헌이익',money(total('test_platform_contribution'))],['강사 몫 누적 발생액',money(total('test_teacher_accrual'))],['직접 추천 누적 발생액',money(total('test_referral_accrual'))],['모의 결제 취소 금액',money(-x.ledger.filter(e=>e.kind==='test_charge_reversal').reduce((n,e)=>n+e.amount,0))]]));for(const [kind,label] of [['test_teacher_accrual','강사별 모의 발생액'],['test_referral_accrual','추천인별 모의 발생액']]){const grouped=new Map();x.ledger.filter(e=>e.kind===kind||e.kind===kind+'_reversal').forEach(e=>{if(e.beneficiary)grouped.set(e.beneficiary,(grouped.get(e.beneficiary)||0)+e.amount);});finance.append(el('h3',label));finance.append(table(['사용자','이름','모의 금액'],[...grouped].map(([uid,amount])=>[uid,x.users.find(u=>u.id===uid)?.nickname||uid,money(amount)])));}root.append(finance);const users=el('div',null,'card');users.append(el('h3','강사 · 회화 파트너 검토'));users.append(table(['이름 / ID','유형 · 상태','자기 기재 경력','작업'],x.users.filter(u=>['partner','teacher'].includes(u.role)).map(u=>[`${u.nickname} / ${u.id}`,`${roles[u.role]} · ${u.approved?'테스트 승인':'대기'}`,u.qualifications||'미등록',button(u.approved?'검토 철회':'테스트 검토',()=>reasonDialog('프로필 테스트 검토',reason=>api('/api/admin/verify','POST',{userId:u.id,approved:!u.approved,reason})))])));root.append(users);const bs=el('div',null,'card');bs.append(el('h3','예약 · 수업 이행 · 모의 정산'));bs.append(table(['예약 / 단원','상태','모의 가격','학습자 / 강사','작업'],x.bookings.map(b=>{const a=el('div',null,'actions');if(b.status==='in_class')a.append(button('증빙 검토',()=>reasonDialog('수업 증빙 검토 · 실제 이행 검증 아님',reason=>api('/api/admin/evidence','POST',{bookingId:b.id,reason}))));if(b.status==='completed')a.append(button('모의 정산 기록',async()=>{await api('/api/admin/settle','POST',{bookingId:b.id});message('모의 원장에 정산 배분을 기록했습니다. 실제 지급은 없습니다.');await render();}));return [`${b.id} / ${b.unit_id}`,statuses[b.status]||b.status,money(b.price),`${b.learner_id} / ${b.teacher_id}`,a];})));root.append(bs);const ds=el('div',null,'card');add(ds,el('h3','신고 · 환불 · 이의신청'),notice('환불은 모의 원장 취소입니다. 이미 발생한 정당한 보수에 대한 자동 삭감·벌금은 없습니다. 재수업은 양측이 같은 새 일정에 동의한 뒤 관리자 검토로 처리합니다. 기존 기록은 감사 이력에 보존됩니다.'));ds.append(table(['사건 / 예약','유형 · 신고 근거','처리','작업'],x.disputes.map(d=>{const a=el('div',null,'actions');if(d.status==='open'){a.append(button('모의 환불',()=>reasonDialog('환불 결정 근거',reason=>api(`/api/admin/disputes/${d.id}`,'POST',{decision:'refund',reason}))));a.append(button('신고 종결',()=>reasonDialog('종결 결정 근거',reason=>api(`/api/admin/disputes/${d.id}`,'POST',{decision:'dismiss',reason}))));a.append(button('합의된 재수업',()=>adminRescheduleDialog(d,x.bookings)));}return [`${d.id} / ${d.booking_id}`,`${d.category}: ${d.reason}`,`${d.status} · ${d.resolution||''}`,a];})));root.append(ds);const ledger=el('div',null,'card');add(ledger,el('h3','거래 · 보상 · 원장 변경 추적'),table(['예약','기록 유형','모의 금액','귀속 사용자','기록 시각'],x.ledger.map(l=>[l.booking_id,l.kind,money(l.amount),l.beneficiary||'플랫폼 / 비용',when(l.created_at)])));root.append(ledger);const audit=el('div',null,'card');add(audit,el('h3','감사 기록 · 최근 500건'),table(['시각','행위자','작업','대상','판단 근거'],x.audit.map(a=>[when(a.created_at),a.actor,a.action,a.entity,a.detail])));root.append(audit);}
