async function diagnosticDialog(unitId,phase,bookingId){
 const {questions}=await api('/api/diagnostics/'+encodeURIComponent(unitId)+'?phase='+phase+(bookingId?'&bookingId='+encodeURIComponent(bookingId):''));
 const box=$('#detail');box.replaceChildren(el('h2',phase==='pre'?'수업 전 내용 확인':'수업 후 내용 확인'),notice('짧은 내용 이해 확인입니다. 실제 발음·말하기는 강사의 수행 평가로 따로 기록합니다.'));
 const form=el('form',null,'stack');questions.forEach((q,i)=>{const group=el('fieldset');group.append(el('legend',`${i+1}. ${q.question}`));q.choices.forEach((choice,j)=>{const label=el('label',choice),radio=el('input');radio.type='radio';radio.name='q'+i;radio.value=j;radio.required=true;label.prepend(radio);group.append(label);});form.append(group);});const submit=el('button','응답 저장 · 채점','primary');submit.type='submit';form.append(submit);form.onsubmit=e=>{e.preventDefault();run(async()=>{const data=new FormData(form),answers=questions.map((_,i)=>Number(data.get('q'+i)));const x=await api('/api/learning/check','POST',{unitId,phase,answers,...(bookingId?{bookingId}:{})});box.replaceChildren(el('h2',`${x.score} / ${x.maxScore}`),notice('기록을 저장했습니다. 나의 학습에서 취약 영역과 다음 수업을 확인하세요.'));},submit);};box.append(form);if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
}
